from pathlib import Path
R=Path(__file__).resolve().parents[3];O=Path(__file__).resolve().parent
L={x['lemma_id']:x for x in json.load(open(R/'lexicon/entries.json',encoding='utf8'))['lemmas']};G={x['feature_id']:x for x in json.load(open(R/'curriculum/grammar.json',encoding='utf8'))['features']};V=json.load(open(O/'verbal-systems.json',encoding='utf8'));M=json.load(open(O/'candidate-models.json',encoding='utf8'))['rows']
S=[];F=[];H=[]
def sense(lid,sid,gloss,status,scope,ev):S.append({'lemma_id':lid,'sense_id':sid,'gloss':gloss,'knowledge_status':status,'scope':scope,'evidence_refs':ev,'prior_senses':[{k:s.get(k)for k in ['sense_id','gloss','production_taught_in','recognition_taught_in','coverage_contract']}for s in L.get(lid,{}).get('senses',[])]})
def feat(fid,label,desc,ev,items,prior=[]):F.append({'feature_id':fid,'label':label,'knowledge_status':'new_production','description':desc,'evidence_refs':ev,'source_items':items,'teaching_id':'NEW-U18-'+fid.upper(),'prior_records':[{k:G[p].get(k)for k in ['feature_id','description','production_taught_in','recognition_taught_in','coverage_contract']}for p in prior if p in G],'scope_limitation':'Only the stated elementary frame is assigned; forms, senses and other constructions retain their separate status.'})
def sup(fid,items,span,desc,ev):H.append({'feature_id':fid,'source_items':items,'knowledge_status':'supplied','support_span':span,'whole_frame_analysis':desc,'evidence_refs':ev,'origin_category':'new editorial support grounded in exact primary material','limitation':'The complete indicated phrase or clause is visible help. Unknown component forms and uses are not tested by independent recall; cumulative parsing can be assessed with the help visible.'})
for s in V['systems']:
 if 'sense_proposal'in s and not any(x['sense_id']==s['sense_proposal']['sense_id']for x in S):
  p=s['sense_proposal'];sense(s['lemma_id'],p['sense_id'],p['gloss'],p['knowledge_status'],p['scope'],s['evidence_refs'])
sense('beodan','beodan-u18-command','command; bid','new_production','Dative addressee with a direct command, or with a ðæt clause in the appropriate subjunctive. The earlier offer sense remains separate.',['U18G-EX31','U18G-EX33','U18G-EX43','U18G-FB94','U18G-FB104'])
sense('don','don-u18-deal-with','deal; behave toward someone','supplied','Only the complete earmlice wið mē dydon clause44.4; do/perform alone is not treated as an independent grant of every interpersonal use.',['U18G-EX29'])
sense('sculan','sculan-u18-future-ellipsis','shall; be yet to come (with an omitted be)','supplied','Only gīet sculon fīf in48.7. It predicts five further years, not five years of personal obligation.',['U18G-EX33','U18G-FB101','U18G-FB102'])
sense('wesan','wesan-u18-anterior-counterfactual','be as auxiliary of counterfactual anterior coming','supplied','Only wē wǣren ... cumen in44.7. Earlier recognition of intransitive perfect does not establish independent mastery of its counterfactual combination.',['U18G-EX29','U18G-FB102','U18G-FB105'])
sense('geseon','geseon-u18-state-content','see how a state of affairs stands','supplied','Only the hū hit mid mē is clause48.10. The reading’s ordinary finite content clause separately reuses supplied geseon-u16-content.',['U18G-EX33','U18G-FB175'])
sense('gesettan','gesettan-u18-appoint-lord','appoint as lord','supplied','Only mē tō hlāforde eallum Egyptum gesętte48.8; bodily placement and the earlier establish sense do not automatically teach the role plus governed-people expression.',['U18G-EX33'])
feat('u18-bethurfan-genitive-relative','Need a thing; relative complement','Beðurfan takes a genitive of the thing needed in the selected ordinary frame, e.g. hwǣtes. In ðā ðing ðe wē beðurfon, ðā ðing is accusative object of buy, while invariant ðe supplies the dependency required by beðurfan within the relative. Its unchanged spelling does not make the internal dependency accusative. BT95 directly quotes this very Genesis43.4/8 clause; it also attests other government, so accusative alternatives are not globally impossible.', ['U18G-BT95','U18G-FB52','U18G-EX29'],['44.3','44.6','NEW-U18-F02'])
feat('u18-oncnawan-object','Recognize an accusative person','Oncnāwan in the selected recognition sense takes an accusative recognized person. The nominative recognizer controls the verb; a change of recognizer from ic to wē changes person/number independently of the object. Present cnāw-/cnǣw- and past cnēow- stay distinct.', ['U18G-EX59','U18G-FB66','U18G-FB67'],['46.4','NEW-U18-F03'])
feat('u18-undon-object','Open an accusative container','Undōn means undo/open the tied sacks in45.8 and takes the accusative container. Present dēð and preterite dyde are different stems; plural preterite undydon follows the plural opener, not the number of sacks.', ['U18G-EX30','U18G-FB79','U18G-FB80'],['45.8','NEW-U18-F03'])
feat('u18-oath-recipient-content','Swear oaths and report their content','Swęrian/swerian takes accusative āðas as the sworn utterance. A dative recipient mīnum fæder48.1 needs no English to; ætforan us44.2 names the people in whose presence it was sworn. The reported content is a ðæt clause: mōsten gives past reported permission, brōhte a promised bringing viewed prospectively from the former oath. The two case frames are not interchangeable.', ['U18G-EX29','U18G-EX32','U18G-FB104'],['44.2','48.1'],['u15-swerian-thurh'])
feat('u18-giernan-propositional-desire','Desire that a state of affairs occur','44.5 retains the explicitly required genitive demonstrative ðæs after giernan, followed by the content-explaining ðæt clause. Lǣdden is first-plural past subjunctive under the former desire; the second ðæt is a conjunction, not a second case-inflected demonstrative. The earlier genitive thing/person request frame alone did not teach this full propositional use.', ['U18G-EX29','U18G-FB91','U18G-FB104'],['44.5'],['u17-giernan-request-woo'])
feat('u18-gedon-object-predicate','Make a person be gracious','Gedōn has accusative person hine plus agreeing accusative masculine singular glædne. In45.2 gedō is third-singular present subjunctive expressing the wish; it is not an imperative addressed to the named Lord. Wið ēow supplies the graciousness target, as the original hint expressly requires.', ['U18G-EX30','U18G-FB97','U18G-FB103'],['45.2'])
feat('u18-agiefan-restoration','Give back a person','Āgiefan selects the returned person as accusative and the recipient as dative. Ēow and ēowerne brōðor have different roles. Present subjunctive āgiefe is in the final purpose clause, not merely an unexplained alternative ending.', ['U18G-EX30','U18G-FB105'],['45.2'])
feat('u18-bereafian-deprivation','Despoil someone of possessions','Berēafian takes accusative person and genitive possessions in its selected active frame. In the passive the deprived person becomes the nominative subject, while genitive mīnra bearna remains.45.6 has genitive plural assena and ðinga; selfe agrees with accusative ūs in the following enslavement clause. BT Supplement81 gives this genitive construction and separately documents instrumental/dative alternatives, which must not be mislabeled impossible.', ['U18G-EX44','U18G-BTS81','U18G-FB91','U18G-FB93'],['45.2','45.6'])
feat('u18-hlystan-genitive','Listen to speech','Hlystan governs genitive speech/content in45.7, as the explicit156 hint directs. Thus ūrre sprǣce is genitive feminine singular, distinct from accusative ūre sprǣce. The people beseech the steward (ðē accusative); ðū is the subject of subordinate hlyste.', ['U18G-EX30','U18G-FB91','U18G-FB104'],['45.7'])
feat('u18-theowian-enslave','Enslave an accusative person','The selected ðēowian sense is enslave, with an accusative person. BT1056 senseII cites precisely Gen43.18, ðæt hē ūs ðēowige. The more common serve sense with different government remains separate. Our ðēowie normalizes the documented -ige/-ie variation under Cook119 and does not change tense or mood.', ['U18G-BT1056','U18G-FB74'],['45.6'])
feat('u18-beodan-command','Command a dative person','Bēodan takes a dative addressee in46.7 and48.8, as164 expressly directs. It can accompany a direct command or introduce ðæt plus subjunctive commanded action.47.11 intentionally retains present bīetst (commandest); the lookalike bīetst of bēatan is not the lexical identity here.', ['U18G-EX31','U18G-EX32','U18G-EX33','U18G-EX43','U18G-FB94','U18G-FB104'],['46.7','47.11','48.8'])
feat('u18-lecgean-placement','Lay out things','Lęcgean takes accusative things laid, with forð marking their presentation in46.3. Its source reading imperative lęcgeað is separately supplied; learning indicative plural lęcgeað does not by itself assign the command use.', ['U18G-EX31','U18G-FB176'],['46.3'])
feat('u18-foresecgean-past-mention','Mention a person earlier to someone','Foresęcgean here means mention previously, not foretell the future. The invariant ðe is the mentioned person (accusative function), and mē the dative hearer. The English of is explicitly omitted. BT Supplement240 distinguishes the past-reference sense and illustrates a person mentioned earlier.', ['U18G-EX31','U18G-BTS240','U18G-FB52'],['46.6'])
feat('u18-ofthyncean-impersonal','Be grieved by a stated circumstance','Ofðyncean is third-singular impersonal with dative experiencer ēow and a cause/content ðæt clause. Present subjunctive ofðynce gives nor let it grieve you; no separately invented personal subject it is needed. The plural experiencer does not demand a plural verb. The four-cell paradigm explicitly limits productive morphology to this impersonal construction.', ['U18G-EX33','U18G-EX49','U18G-FB70','U18G-FB102'],['48.6'])
feat('u18-ondraedan-genitive','Fear with genitive object and reflexive dative','48.6 extends the previously taught accusative feared-entity frame to the directly attested genitive frame: reflexive dative ēow plus nānes ðinges. Cook156h/159a explicitly gives ne ondrǣd ðū ðē ǣniges ðinges.46.1 has only the reflexive dative, with no expressed feared entity. This ēow is not an accusative object merely because its spelling is syncretic.', ['U18G-FB92','U18G-FB93','U18G-EX30','U18G-EX33'],['46.1','48.6'],['u13-ondraedan-acc'])
feat('u18-forgieldan-good-evil','Requite good with evil','In46.9 accusative neuter gōd is the good being repaid; mid yfele is the evil given in return. The recipient frame previously used for paying is not by itself this good-for-evil substitution frame. Wolden is third-plural past subjunctive inside the reported why-question; forgieldan is its plain infinitive.', ['U18G-EX31','U18G-EX59','U18G-FB104'],['46.9'])
feat('u18-prospective-when','Prospective when with subjunctive','46.9 when you have caught them concerns a future condition for the command to ask. The selected ðonne ðū hīe fō uses second-singular present subjunctive, following196b. There is no required present-perfect auxiliary. Original English says you, and the singular steward continues as addressee of Ārīs, gā and āsca.', ['U18G-EX31','U18G-FB105'],['46.9'])
feat('u18-relative-subjunctive-attraction','Subjunctive within an optative relative','47.3 retains195: in sīe hē ofslægen mid ðǣm ðe ðū hit finde, finde is second-singular present subjunctive within the relative governed by the hypothetical/optative context. Mid takes a dative associate; ðe is invariant. This is not a rule that every relative clause uses subjunctive.', ['U18G-EX32','U18G-FB104','U18G-FB105'],['47.3'])
feat('u18-preterite-anterior-review','Narrative preterite with anterior meaning','Cook188 permits the simple preterite for English simple, perfect and pluperfect past. In45.8 cēapodon and ǣr sealdon give the anterior actions;46.9 fōron ... sumne dǣl ðæs weges conveys had gone without an unassigned intransitive habban perfect. Each clause remains present in the model.', ['U18G-FB101','U18G-FB102','U18G-EX30','U18G-EX31'],['45.8','45.9','46.9'],['u12-preterite-anterior','u17-past-tense-selection'])
feat('u18-diernan-reflexive','Conceal oneself','Diernan takes the concealed person as accusative; hine in48.4 refers back to nominative Iosep. Meahte is past ability and governs the plain infinitive. Longer is an adverb modifying concealment, not an adjective agreeing with Joseph.', ['U18G-EX32','U18G-FB101'],['48.4'])
sup('U18-H-44-04',['44.4'],'Gē earmlice wið mē dydon','Complete interpersonal clause: you behaved/dealt badly toward me. Wið names the affected counterpart; it is not a physical battle assertion. Dydon agrees with plural gē.', ['U18G-EX29'])
sup('U18-H-44-07',['44.7'],'Gif ðēos ęlcung nǣre, wē wǣren ōðre sīðe cumen','Complete contrary condition and anterior result: if this delay were not, we would already have come a second time. Nǣre is ne+wǣre, third-singular past subjunctive; wǣren is first-plural past subjunctive. Cumen is a past participle with intransitive wesan, not the identically spelled present-subjunctive plural. Ōðre sīðe is adverbial instrumental singular, expressly176; the sīð hint names the lemma and does not suppress its ending. The entire combined construction and contracted form are supplied; no general counterfactual-perfect mastery is inferred.', ['U18G-EX29','U18G-FB63','U18G-FB79','U18G-FB99','U18G-FB102','U18G-FB105'])
sup('U18-H-45-05',['45.5','47.2'],'hē dyde swā him boden wæs','Impersonal command passive: he did as was commanded him. Him is dative addressee; boden wæs is singular without promoting him to nominative. Cook177.10 swā hiere beboden wæs is the explicitly cited parallel; replacing be-bēodan with independently attested command bēodan is a declared lexical adaptation.', ['U18G-EX30','U18G-EX31','U18G-FB177','U18G-EX43','U18G-FB101','U18G-FB102'])
sup('U18-H-45-06-PASSIVE',['45.6'],'wē sindon hider in lǣded','We have been led in hither. Present wesan plus the past participle is the selected passive/result expression; uninflected lǣded with plural wē is expressly allowed by62. Inflected plural lǣdde is not needed to satisfy the prompt and is not silently treated as taught.', ['U18G-EX30','U18G-FB41','U18G-FB101'])
sup('U18-H-45-09',['45.9'],'and ēac ōðer seolfor mid tō cēapianne','The earlier we brought governs the coordinated silver-object; mid marks silver as the instrument of trading and is stranded before the purposive inflected infinitive. This does not require a new finite verb or make the silver a human trading partner. Supply the whole compressed phrase.', ['U18G-EX30','U18G-FB106'])
sup('U18-H-46-01',['46.1'],'ēower God and ēowres fæder God sealde ēow goldhord','The one deity is described as your God and your father’s God, explaining singular sealde. Ēowres agrees with the genitive father; second ēow is dative recipient. The expression does not assert two gods.', ['U18G-EX30','U18G-FB102'])
sup('U18-H-46-03',['46.3'],'ongēan ðætte Iosep inēode','Against/in readiness for Joseph’s entering. The gifts are laid out in preparation for this prospective arrival; inēode is third-singular past subjunctive, an already productive ingān cell. The whole source conjunction is supplied, not equated with spatial against.', ['U18G-EX31','U18G-FB105'])
sup('U18-H-46-08',['46.8'],'nim mīnne seolfrenne læfel, and ðæs hwǣtes weorð ðe hē ðē sealde, and dō on ðæs gingstan sacc','Supplied seolfrenne is the strong accusative masculine singular adjective agreeing with the cup; ðæs hwǣtes specifies the wheat price, and the price is what he gave thee. The coordinated put shares the cup-and-price objects; no unprinted singular it is required. The youngest is the substantival weak adjective identifying the sack’s possessor. The nominal/source packet supplies the exact silver-adjective form with evidence; no independent adjective system is inferred.', ['U18G-EX31','U18G-EX62'])
sup('U18-H-47-04',['47.4'],'Mid swā hwǣm swā ic hit finde, sīe hē mīn ðēow, and sīen ðā ōðre clǣne','The free-choice dative person is governed by mid within the indefinite condition; hē resumes that person as subject of the singular wish. The other people are plural subject of sīen. Clǣne means clear of blame here. Preserve the scope contrast between the one offender and the other people.', ['U18G-EX32','U18G-FB52','U18G-FB103','U18G-FB105'])
sup('U18-H-47-11',['47.11'],'ðū bīetst ūs ðæt wē hine ðē bringen, ðæt ðū hine gesēo, and wite be ðǣm ðæt wē ne wǣren scēaweras','Retain actual present commandest: bīetst is present second singular, not an editorial backshift. The commanded bringing has first-plural present subjunctive; seeing and knowing are coordinated second-singular present subjunctives under purpose. The final reported status preserves original were as first-plural past subjunctive. Be ðǣm means by that evidence, and its following ðæt introduces the content known. The complete tense and proof chain is supplied.', ['U18G-EX32','U18G-FB104','U18G-FB105'])
sup('U18-H-48-03',['48.3'],'Ic ne dearr hām gān būtan ðǣm cnapan, ðȳ-lǣs-ðe ic mīnes fæder sārnesse gesēo','Negative present dare plus plain go has the same speaker subject. Būtan with dative denotes absence of the boy, not the unless conjunction used elsewhere. The following negative-purpose clause lest I see uses first-singular present subjunctive gesēo; it does not assert that the grief was seen. Father is genitive possessor within accusative grief.', ['U18G-EX32','U18G-FB77','U18G-FB95','U18G-FB105'])
sup('U18-H-48-05',['48.5'],'clēopode hlūdre stefne','Exact48.5 hint has marked clēopian. Supply the derived weakII past third singular clēopode and the dative/instrumental voice phrase meaning cried with a loud voice. Keep the earlier cleopian records unchanged; the marked source variant is not silently substituted into earlier paradigms.', ['U18G-EX33','U18G-FB73','U18G-FB74','U18G-FB93'])
sup('U18-H-48-07',['48.7'],'Nū twā gēar hunger wæs ofer ealle eorðan, and gīet sculon fīf, on ðǣm mann nāhwæðer ne ęrian ne rīpan mæg','Two years is accusative duration; singular hunger governs wæs. Ofer takes accusative extent ealle eorðan, as172 requires. Fīf stands for five further years; the source explicitly omits there and be, so sculon has an understood existential complement, not a missing translation item. On ðǣm refers to those years. Indefinite mann is singular subject of mæg; nāhwæðer plus ne...ne excludes both infinitive activities. Cook89a supplies the full pronoun; BT Supplement646 independently attests the equivalent contracted nāðer with paired negated infinitives under mihte. All ellipsis, future use and negative coordination are supplied together.', ['U18G-EX33','U18G-FB52','U18G-FB96','U18G-FB101','U18G-FB102','U18G-BTS646'])
sup('U18-H-48-08',['48.8'],'God mē tō hlāforde eallum Egyptum gesętte','God appointed me as lord to all Egyptians. Mē is the accusative appointee, tō hlāforde the role complement, and eallum Egyptum the dative people governed; omit the English to as instructed rather than adding an unsolicited ofer. The name phrase is supplied by the nominal/source packet.', ['U18G-EX33'])
sup('U18-H-48-10',['48.10'],'Nū gē gesēoð hū hit mid mē is, and gē hīerað hwæt ic tō ēow sprece','Hū introduces how things stand with the speaker; this is a state-of-affairs expression, not physical accompaniment. Hwæt is what he says, heard by plural gē. Sprece retains the first-singular speaker, and tō ēow the plural addressee.', ['U18G-EX33','U18G-FB104'])
sup('U18-H-48-02',['48.2'],'lǣt ðone cnapan mid his brōðrum hām gān','Complete permission frame: singular lǣt addresses Joseph; accusative ðone cnapan is the actor of plain infinitive gān. The boy goes home with his brothers. The accusative actor is not the recipient of a finite command and gān has no person ending. This local frame does not infer unrestricted causative/permissive infinitives from the familiar verb alone.', ['U18G-EX32','U18G-FB96','U18G-FB105','U18G-FB106'])
refs=[]
for h in json.load(open(R/'sources/audits/unit18-source/exercise-hints.json',encoding='utf8'))['records']:
 if any(w in h['exact_text']for w in ['beðurfan','giernan','hlystan','lęcgean','foresęcgean','forstelan','stelan','clēopian','ęrian','rīpan']):refs.append({'source_item_id':h['source_item_id'],'hint_id':h['hint_id'],'exact_text':h['exact_text'],'knowledge_status':'supplied','scope':'Original dictionary/lexical hint stays visible; reading it is not independent recall of an otherwise unassigned infinitive or conjugation.'})
D={'schema_version':1,'status':'precontract source-checked scope proposal; no active-register mutations','sense_proposals':S,'features':F,'whole_frame_support':H,'dictionary_reference_positions':refs,'prior_sense_reuse':[],'still_pending':[]}
(O/'senses-constructions-support.json').write_text(json.dumps(D,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print(len(S),'senses',len(F),'features',len(H),'whole supports')
